"""bend_own.h (generated by tools/gen_bend_own.py from 2^(k/48) - 1 in Q30) holds exactly engine.c's ENG_BEND_T."""
import os
import re

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))


def ints(path, name):
    s = open(os.path.join(ROOT, path)).read()
    m = re.search(name + r"\[17\] = \{(.*?)\};", s, re.S)
    return [int(x) for x in re.sub(r"/\*.*?\*/", "", m.group(1), flags=re.S).replace("\n", " ").split(",")]


def test_own_bend_equals_eng_bend_t():
    own = ints("firmware/src/bend_own.h", "BEND_OWN_T")
    assert len(own) == 17
    assert own == ints("firmware/src/engine.c", "ENG_BEND_T")


def test_own_bend_header_is_generated():
    import importlib.util
    spec = importlib.util.spec_from_file_location("gen_bend_own", os.path.join(ROOT, "tools", "gen_bend_own.py"))
    g = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(g)
    assert open(os.path.join(ROOT, "firmware", "src", "bend_own.h")).read() == g.render()
